CREATE OR REPLACE FUNCTION public.bm_inbox_can_message(_sender uuid,_recipient uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.has_any_role(_sender,ARRAY['admin','management']::app_role[]) THEN true ELSE CASE COALESCE((SELECT inbox_privacy FROM profiles WHERE id=_recipient),'everyone') WHEN 'everyone' THEN true WHEN 'nobody' THEN false WHEN 'staff' THEN public.has_any_role(_sender,ARRAY['staff','moderator']::app_role[]) WHEN 'friends' THEN EXISTS(SELECT 1 FROM friendships WHERE status::text='accepted' AND ((requester_id=_sender AND addressee_id=_recipient) OR (requester_id=_recipient AND addressee_id=_sender))) ELSE true END END $$;
CREATE OR REPLACE FUNCTION public.forum_board_allows(_user uuid,_board uuid,_action text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE configured boolean; BEGIN IF public.has_any_role(_user,ARRAY['admin','boro_fan_zone_moderator']::app_role[]) THEN RETURN true; END IF; IF NOT (_user=auth.uid() AND public.customer_profile_restricted()) AND EXISTS(SELECT 1 FROM public.forum_board_moderators WHERE board_id=_board AND user_id=_user) THEN RETURN true; END IF; SELECT EXISTS(SELECT 1 FROM public.forum_board_permissions WHERE board_id=_board) INTO configured; IF configured THEN RETURN EXISTS(SELECT 1 FROM public.forum_board_permissions p JOIN public.user_roles ur ON ur.role=p.role WHERE p.board_id=_board AND ur.user_id=_user AND public.has_role(_user,ur.role) AND CASE _action WHEN 'view' THEN p.can_view WHEN 'create_topic' THEN p.can_create_topic WHEN 'reply' THEN p.can_reply ELSE false END); END IF; RETURN public.is_fan_zone_member(_user); END $$;